<script lang="ts">
 import {onMount,tick} from 'svelte'
 import {terminalClosed,type TerminalMachine,type TerminalSession} from './api'
 let {machines,sessions,selectedAgent,selectedSession,width=$bindable(280),preferenceKey,onmachine,onselect,onclose,onrefresh,onaction,ondisconnect,busy=false}:{machines:TerminalMachine[];sessions:TerminalSession[];selectedAgent:string;selectedSession:string;width?:number;preferenceKey:string;onmachine:(id:string)=>void;onselect:(item:TerminalSession)=>void;onclose:()=>void;onrefresh:()=>void;onaction:(kind:'rename'|'end'|'archive',item:TerminalSession)=>void;ondisconnect:()=>void;busy?:boolean}=$props()
 let machineFilterOpen=$state(false)
 let query=$state(''),sort=$state('custom'),group=$state('machine'),filter=$state<string[]|null>(null),order=$state<string[]>([]),colors=$state<Record<string,string>>({}),notice=$state('')
 const palette=[{id:'none',name:'No colour',hex:'transparent'},{id:'red',name:'Red',hex:'#d95757'},{id:'amber',name:'Amber',hex:'#c48b2f'},{id:'green',name:'Green',hex:'#3f9c72'},{id:'blue',name:'Blue',hex:'#598ed7'},{id:'violet',name:'Violet',hex:'#a17ed1'}]
 let sidebar=$state<HTMLElement>(),menu=$state<HTMLElement>(),context=$state<{item:TerminalSession;x:number;y:number}|null>(null),returnFocus:HTMLElement|undefined,dragging=''
 const machineName=(id:string)=>machines.find(item=>item.agentId===id)?.host||'Unavailable machine'
 const matches=$derived(sessions.filter(item=>(filter===null||filter.includes(item.agentId))&&`${item.title} ${machineName(item.agentId)} ${item.state.replaceAll('_',' ')}`.toLowerCase().includes(query.toLowerCase())))
 const sorted=$derived.by(()=>{const ranked=new Map(order.map((id,i)=>[id,i]));return [...matches].sort((a,b)=>{if(sort==='name')return a.title.localeCompare(b.title)||a.id.localeCompare(b.id);if(sort==='recent')return b.updatedAt-a.updatedAt||a.id.localeCompare(b.id);if(sort==='created')return b.createdAt-a.createdAt||a.id.localeCompare(b.id);if(sort==='status')return a.state.localeCompare(b.state)||a.title.localeCompare(b.title)||a.id.localeCompare(b.id);return (ranked.get(a.id)??Number.MAX_SAFE_INTEGER)-(ranked.get(b.id)??Number.MAX_SAFE_INTEGER)||a.createdAt-b.createdAt||a.id.localeCompare(b.id)})})
 function groupKey(item:TerminalSession){return group==='machine'?item.agentId:group==='status'?item.state:group==='colour'?(colors[item.id]||'none'):''}
 const groups=$derived.by(()=>{const out=new Map<string,{key:string;title:string;items:TerminalSession[]}>();for(const item of sorted){const key=groupKey(item);if(!out.has(key))out.set(key,{key,title:group==='machine'?machineName(key):group==='status'?key.replaceAll('_',' '):group==='colour'?(palette.find(c=>c.id===key)?.name||'No colour'):'',items:[]});out.get(key)!.items.push(item)}return [...out.values()]})
 const filterValue=$derived(filter===null?'*':filter.length===1?filter[0]:'selected')
 function persist(){try{localStorage.setItem(preferenceKey,JSON.stringify({sort,group,filter,order,colors}))}catch{/* browser storage is optional */}}
 onMount(()=>{try{const saved=JSON.parse(localStorage.getItem(preferenceKey)||'{}');if(['custom','name','recent','created','status'].includes(saved.sort))sort=saved.sort;if(['none','machine','status','colour'].includes(saved.group))group=saved.group;if(Array.isArray(saved.filter)&&saved.filter.every((v:unknown)=>typeof v==='string'))filter=saved.filter.slice(0,256);if(Array.isArray(saved.order))order=[...new Set(saved.order.filter((v:unknown)=>typeof v==='string'))].slice(0,2000) as string[];if(saved.colors&&typeof saved.colors==='object'&&!Array.isArray(saved.colors))colors=Object.fromEntries(Object.entries(saved.colors).filter((entry):entry is [string,string]=>typeof entry[1]==='string'&&palette.some(c=>c.id===entry[1])))}catch{/* ignore an invalid preference */}})
 function selectMachine(value:string){if(value==='*')filter=null;else if(value==='selected'){filter=filter||[selectedAgent];machineFilterOpen=true}else{filter=[value];onmachine(value)}persist()}
 function toggleMachine(id:string,checked:boolean){const selected=filter||machines.map(item=>item.agentId);filter=checked?[...new Set([...selected,id])]:selected.filter(value=>value!==id);persist()}
 async function openMenu(event:MouseEvent|KeyboardEvent,item:TerminalSession){event.preventDefault();returnFocus=event.currentTarget as HTMLElement;const box=returnFocus.getBoundingClientRect();context={item,x:Math.min(Math.max(8,'clientX'in event&&event.clientX?event.clientX:box.left),Math.max(8,innerWidth-240)),y:Math.max(8,Math.min('clientY'in event&&event.clientY?event.clientY:box.bottom,innerHeight-330))};await tick();menu?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()}
 function closeMenu(focus=true){context=null;if(focus)returnFocus?.focus()}
 function menuKey(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();closeMenu();return}if(event.key==='Tab'){closeMenu(false);return}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...menu!.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')],index=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}
 function action(kind:'rename'|'end'|'archive'){if(!context)return;const item=context.item;closeMenu(false);onaction(kind,item)}
 function colour(id:string){if(!context)return;colors={...colors,[context.item.id]:id};persist()}
 function move(id:string,target:string){if(id===target||sort!=='custom')return;const from=sessions.find(item=>item.id===id),to=sessions.find(item=>item.id===target);if(!from||!to)return;if(groupKey(from)!==groupKey(to)){notice='Move within a group, or choose No grouping to reorder across groups.';return}const ids=[...order,...sorted.map(item=>item.id)].filter((value,index,all)=>value!==id&&all.indexOf(value)===index);ids.splice(Math.max(0,ids.indexOf(target)),0,id);order=ids;notice='Session order saved in this browser.';persist()}
 function moveBy(delta:number){if(!context)return;const rows=groups.find(item=>item.key===groupKey(context!.item))?.items||[],index=rows.findIndex(item=>item.id===context!.item.id),target=rows[index+delta];if(!target)return;if(delta<0)move(context.item.id,target.id);else move(target.id,context.item.id)}
 function startDrag(event:DragEvent,item:TerminalSession){if(sort!=='custom'){event.preventDefault();return}dragging=item.id;event.dataTransfer?.setData('application/x-reet-session',item.id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
 function drop(event:DragEvent,item:TerminalSession){event.preventDefault();if(dragging&&event.dataTransfer?.getData('application/x-reet-session')===dragging)move(dragging,item.id);dragging=''}
 function resize(event:PointerEvent){event.preventDefault();const target=event.currentTarget as HTMLElement;target.setPointerCapture(event.pointerId)}
 function resizeMove(event:PointerEvent){const target=event.currentTarget as HTMLElement;if(!target.hasPointerCapture(event.pointerId)||!sidebar)return;width=Math.round(Math.max(220,Math.min(480,innerWidth*.8,event.clientX-sidebar.getBoundingClientRect().left)))}
 function resizeKey(event:KeyboardEvent){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();width=event.key==='Home'?220:event.key==='End'?480:Math.max(220,Math.min(480,width+(event.key==='ArrowLeft'?-16:16)))}
</script>
<svelte:window onpointerdown={event=>{if(context&&!menu?.contains(event.target as Node))closeMenu(false)}} onblur={()=>closeMenu(false)} />
<aside bind:this={sidebar} id="terminal-sessions" class="session-sidebar" aria-label="Session navigation">
 <header><strong>Your sessions <small>{matches.length}</small></strong><button class="collapse" onclick={onclose} aria-label="Close session navigation" title="Collapse sessions">‹</button></header>
 <label class="machine-label">Machines<select aria-label="Machine" value={filterValue} onchange={event=>selectMachine(event.currentTarget.value)}><option value="*">All machines</option>{#each machines as machine(machine.agentId)}<option value={machine.agentId}>{machine.host}{machine.ready?' · Ready':''}</option>{/each}<option value="selected">Select machines…</option></select></label>
 <details class="machine-filter" bind:open={machineFilterOpen}><summary>Choose multiple machines</summary><div><button class="link" onclick={()=>{filter=null;persist()}}>Show all machines</button>{#each machines as machine(machine.agentId)}<label><input type="checkbox" checked={filter===null||filter.includes(machine.agentId)} onchange={event=>toggleMachine(machine.agentId,event.currentTarget.checked)}/><span>{machine.host}</span></label>{/each}</div></details>
 <label><span class="vh">Find sessions</span><input type="search" bind:value={query} placeholder="Find a session or machine…" aria-label="Find sessions" /></label>
 <div class="organise"><label>Sort<select aria-label="Sort sessions" value={sort} onchange={event=>{sort=event.currentTarget.value;persist()}}><option value="custom">Custom order</option><option value="name">Name</option><option value="recent">Recently updated</option><option value="created">Newest first</option><option value="status">Status</option></select></label><label>Group<select aria-label="Group sessions" value={group} onchange={event=>{group=event.currentTarget.value;persist()}}><option value="none">No grouping</option><option value="machine">Machine</option><option value="status">Status</option><option value="colour">Colour</option></select></label></div>
 <nav aria-label="Terminal sessions">{#each groups as section(section.key)}<section class="session-group">{#if section.title}<h2>{section.title}<small>{section.items.length}</small></h2>{/if}<ul>{#each section.items as item(item.id)}<li class:selected={item.id===selectedSession} style={`--session-colour:${palette.find(c=>c.id===colors[item.id])?.hex||'transparent'}`} ondragover={event=>{if(dragging)event.preventDefault()}} ondrop={event=>drop(event,item)}>
  <button class="session-row" aria-current={item.id===selectedSession?'true':undefined} onclick={()=>onselect(item)} oncontextmenu={event=>openMenu(event,item)} onkeydown={event=>{if(event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')void openMenu(event,item)}}><span class="session-dot" class:running={item.state==='running'} aria-hidden="true"></span><span><strong>{item.title}</strong><small>{group!=='machine'?`${machineName(item.agentId)} · `:''}{item.state.replaceAll('_',' ')}</small></span></button>
  <button class="row-actions" aria-label={`Actions for ${item.title}`} title={sort==='custom'?'Session actions · drag to reorder':'Session actions'} draggable={sort==='custom'} ondragstart={event=>startDrag(event,item)} ondragend={()=>dragging=''} onclick={event=>openMenu(event,item)} oncontextmenu={event=>openMenu(event,item)}>⋮</button>
 </li>{/each}</ul></section>{:else}<p class="empty">{query?'No matching sessions.':'No sessions in this selection.'}</p>{/each}</nav>
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}<footer><button class="link" onclick={onrefresh}>Refresh status</button><a href="/machines">Manage machines →</a><small>Layout, colours and order saved in this browser. Use Custom order to drag sessions.</small></footer>
 <!-- A focusable ARIA window splitter supports arrow keys and pointer capture. -->
 <!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions -->
 <div class="resize-handle" role="separator" tabindex="0" aria-label="Resize session navigation" aria-orientation="vertical" aria-valuemin="220" aria-valuemax="480" aria-valuenow={width} onpointerdown={resize} onpointermove={resizeMove} onkeydown={resizeKey}></div>
</aside>
{#if context}<div class="session-context" role="menu" aria-label={`Actions for ${context.item.title}`} tabindex="-1" bind:this={menu} style={`left:${context.x}px;top:${context.y}px`} onkeydown={menuKey}>
 <p>{context.item.title}<small>{machineName(context.item.agentId)}</small></p>
 <button role="menuitem" disabled={busy||machines.find(m=>m.agentId===context!.item.agentId)?.serverEnabled===false} onclick={()=>action('rename')}>Rename session</button>
 <button role="menuitem" disabled={context.item.id!==selectedSession||terminalClosed(context.item.state)} onclick={()=>{closeMenu(false);ondisconnect()}}>Disconnect this browser</button>
 {#if terminalClosed(context.item.state)}<button role="menuitem" disabled={busy} onclick={()=>action('archive')}>Remove from history…</button>{:else}<button role="menuitem" class="danger" disabled={busy||machines.find(m=>m.agentId===context!.item.agentId)?.serverEnabled===false} onclick={()=>action('end')}>{context.item.state==='end_requested'?'Retry end request…':'Stop session…'}</button>{/if}
 <div class="menu-order"><button role="menuitem" disabled={sort!=='custom'} onclick={()=>moveBy(-1)}>Move up</button><button role="menuitem" disabled={sort!=='custom'} onclick={()=>moveBy(1)}>Move down</button></div>
 <span class="colour-label">Session colour</span><div class="colours">{#each palette as choice}<button role="menuitemradio" aria-checked={(colors[context.item.id]||'none')===choice.id} aria-label={choice.name} title={choice.name} style={`--swatch:${choice.hex}`} onclick={()=>colour(choice.id)}>{choice.id==='none'?'×':''}</button>{/each}</div>
</div>{/if}
<style>
 .session-sidebar{position:relative;display:flex;flex-direction:column;gap:12px;background:var(--bg);border-right:1px solid var(--line);padding:14px;min-height:0;min-width:0;overflow:auto}header{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:.82rem}header small{color:var(--muted);font-size:.65rem;font-weight:400;margin-left:6px}.collapse{background:none;border:0;border-radius:5px;cursor:pointer;font-size:1.5rem;color:var(--muted);min-width:28px;min-height:28px}.collapse:hover{background:var(--tint);color:var(--accent)}label{display:grid;gap:5px;min-width:0;font-size:.65rem;color:var(--muted)}input:not([type=checkbox]),select{width:100%;min-width:0;min-height:34px;padding:6px 8px;font-size:.74rem}.machine-label{font-size:.64rem}.machine-filter{font-size:.67rem;color:var(--muted);margin-top:-6px}.machine-filter summary{cursor:pointer}.machine-filter>div{display:grid;gap:9px;padding:12px 0 3px}.machine-filter label{display:flex;align-items:center;gap:7px}.machine-filter label span{overflow-wrap:anywhere}.machine-filter input{margin:0;accent-color:var(--accent)}.organise{display:grid;grid-template-columns:1fr 1fr;gap:8px}.organise select{font-size:.68rem;min-height:30px;padding:5px}nav{display:grid;gap:16px;align-content:start}.session-group{min-width:0}.session-group h2{font-size:.64rem;color:var(--muted);margin:0 2px 7px;text-transform:capitalize;display:flex;gap:8px;overflow-wrap:anywhere}.session-group h2 small{margin-left:auto;font-size:.6rem;font-weight:400}ul{list-style:none;display:grid;gap:4px;margin:0;padding:0}li{display:flex;align-items:stretch;border:1px solid transparent;border-left:3px solid var(--session-colour);border-radius:7px;min-width:0}li.selected{background:var(--card);border-top-color:var(--line);border-right-color:var(--line);border-bottom-color:var(--line)}li:hover{background:var(--card)}.session-row{display:flex;gap:8px;align-items:flex-start;text-align:left;flex:1;min-width:0;padding:9px 5px;background:transparent;border:0;color:var(--ink);cursor:pointer}.session-row>span:last-child{display:grid;gap:4px;min-width:0}.session-row strong{font-size:.74rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.session-row small{font-size:.61rem;color:var(--muted);text-transform:capitalize;overflow-wrap:anywhere}.session-dot{height:6px;width:6px;flex:none;background:var(--muted);border-radius:50%;margin-top:5px}.session-dot.running{background:var(--good)}.row-actions{width:28px;flex:none;border:0;border-radius:5px;background:transparent;color:var(--muted);cursor:pointer;font-size:1.2rem}.row-actions[draggable=true]{cursor:grab}.row-actions:hover{color:var(--accent);background:var(--tint)}.empty,.notice{font-size:.72rem;color:var(--muted);line-height:1.6}.notice{margin:0}footer{margin-top:auto;display:grid;gap:12px;padding-top:16px}.link,footer>a{font-size:.7rem;text-decoration:none;text-align:left;border:0;background:none;padding:0;color:var(--accent);cursor:pointer}.link:hover,footer>a:hover{text-decoration:underline}footer small{font-size:.6rem;line-height:1.6;color:var(--muted)}.resize-handle{position:absolute;right:0;top:0;bottom:0;width:6px;cursor:col-resize;touch-action:none;z-index:2}.resize-handle:hover,.resize-handle:focus-visible{background:var(--accent);outline:0}.session-context{position:fixed;z-index:40;width:232px;max-height:calc(100dvh - 16px);overflow:auto;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--card);box-shadow:0 12px 35px rgb(0 0 0 / .2);display:grid;gap:2px}.session-context>p{font-size:.74rem;font-weight:600;overflow-wrap:anywhere;margin:5px 8px 8px}.session-context p small{display:block;font-size:.63rem;color:var(--muted);font-weight:400;margin-top:4px}.session-context button{min-height:32px;background:none;border:0;border-radius:5px;padding:7px 9px;text-align:left;font-size:.72rem;color:var(--ink);cursor:pointer}.session-context button:hover,.session-context button:focus-visible{background:var(--tint)}.session-context button:disabled{opacity:.4;cursor:default}.session-context button.danger{color:var(--bad)}.menu-order{border-top:1px solid var(--line);margin-top:4px;padding-top:4px;display:flex}.menu-order button{flex:1}.colour-label{font-size:.62rem;color:var(--muted);margin:8px}.colours{display:flex;gap:5px;padding:0 7px 6px}.colours button{border:1px solid var(--line);background:var(--swatch);padding:0;height:24px;width:24px;min-height:24px;text-align:center}.colours button[aria-checked=true]{outline:2px solid var(--ink);outline-offset:2px}.vh{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:959px){.session-sidebar{position:absolute;inset:0 auto 0 0;width:min(85%,var(--sidebar-width));z-index:8;box-shadow:12px 0 30px rgb(0 0 0 / .12)}.resize-handle{display:none}}@media(pointer:coarse){.collapse,.row-actions,.session-context button{min-height:40px}.colours button{height:30px;width:30px}}
</style>
